create table public.tax_exemptions (id uuid primary key default gen_random_uuid(), taxpayer_id uuid not null, tax_category_id uuid references public.tax_categories(id), jurisdiction_id uuid references public.tax_jurisdictions(id), certificate_id text, exemption_reason text, effective_from timestamptz not null, effective_to timestamptz, active boolean not null default true, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), check(effective_to is null or effective_to>effective_from));
create table public.tax_transactions (id uuid primary key default gen_random_uuid(), order_id uuid references public.orders(id), buyer_id uuid, seller_id uuid, affiliate_id uuid, provider_id uuid, jurisdiction_id uuid references public.tax_jurisdictions(id), taxpayer_role text not null check(taxpayer_role in('platform','seller','buyer','affiliate','provider','other')), tax_period text, currency char(3) not null, gross_amount numeric(20,8) not null default 0, taxable_amount numeric(20,8) not null default 0, tax_amount numeric(20,8) not null default 0, status text not null default 'calculated' check(status in('calculated','collected','withheld','reported','reversed','void')), snapshot jsonb not null, source_type text not null default 'order', source_reference text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(gross_amount>=0 and taxable_amount>=0 and tax_amount>=0));
create table public.tax_transaction_lines (id uuid primary key default gen_random_uuid(), tax_transaction_id uuid not null references public.tax_transactions(id) on delete cascade, tax_rule_id uuid references public.tax_rules(id), tax_category_id uuid references public.tax_categories(id), jurisdiction_id uuid references public.tax_jurisdictions(id), taxpayer_id uuid, responsible_party text not null check(responsible_party in('platform','seller','buyer','affiliate','provider','other')), collected_by text not null check(collected_by in('platform','seller','third_party','none')), tax_type text not null, rate numeric(12,8) not null default 0, taxable_amount numeric(20,8) not null default 0, tax_amount numeric(20,8) not null default 0, currency char(3) not null, snapshot jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), check(rate>=0 and taxable_amount>=0 and tax_amount>=0));
create table public.tax_withholdings (id uuid primary key default gen_random_uuid(), tax_transaction_id uuid references public.tax_transactions(id), order_id uuid references public.orders(id), payee_id uuid not null, jurisdiction_id uuid references public.tax_jurisdictions(id), tax_type text not null, rate numeric(12,8) not null default 0, base_amount numeric(20,8) not null default 0, withheld_amount numeric(20,8) not null default 0, currency char(3) not null, status text not null default 'pending' check(status in('pending','held','remitted','reversed','void')), snapshot jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(rate>=0 and base_amount>=0 and withheld_amount>=0));
